namespace Framework.Movement
{
    /// <summary>
    /// グリッド経路追従の実行状態を表す。
    /// </summary>
    public enum GridPathFollowerState
    {
        /// <summary>
        /// 経路が設定されていない状態。
        /// </summary>
        Idle = 0,

        /// <summary>
        /// 設定された経路を追従している状態。
        /// </summary>
        Following = 1,

        /// <summary>
        /// 経路追従を一時停止している状態。
        /// </summary>
        Paused = 2,

        /// <summary>
        /// 目的地への到達が完了した状態。
        /// </summary>
        Completed = 3,

        /// <summary>
        /// 経路追従に失敗した状態。
        /// </summary>
        Failed = 4,

        /// <summary>
        /// 経路追従が中断された状態。
        /// </summary>
        Cancelled = 5,

        /// <summary>
        /// リソースが解放された状態。
        /// </summary>
        Disposed = 6
    }
}
